import{z as s,x as n,o,c as p,q as t,j as i,D as r,d as a,s as l,S as A,b as B}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"信用组合模型","description":"","frontmatter":{"title":"信用组合模型","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc-credit-portfolio.md","filePath":"quant/rc-credit-portfolio.md","lastUpdated":1791413859000}'),h={name:"quant/rc-credit-portfolio.md"};function D(d,E,u,c,m,C){const e=n("Mermaid");return o(),p("div",null,[E[2]||(E[2]=t('<h1 id="信用组合模型" tabindex="-1">信用组合模型 <a class="header-anchor" href="#信用组合模型" aria-label="Permalink to &quot;信用组合模型&quot;">​</a></h1><div class="epigraph"><p>分散化在信用组合的尾部会失灵：当共同因子落下来的时候，所有名字一起倒下；平均损失几乎不动，极端损失却成倍放大。</p><footer>—— 据 Vasicek, *The Distribution of Loan Portfolio Value*, Risk, 2002；Li, *Journal of Fixed Income*, 2000 整理</footer></div><p><a href="/quant/rc-rate-vol">上一课</a>以利率波动率曲面收束了利率侧三课，本课程从此转入信用与资金单元。单名 CDS 的生存曲线自举（见<a href="/quant/cds-survival-bootstrap">CDS 生存曲线自举</a>）给每个名字各自的边际违约概率，但组合的问题不在边际而在联合：违约如何相关、损失分布的尾部多厚、把名字换成分层之后价格怎么变。本课讲信用组合模型——从一因子 copula 到因子模拟与精算模型——为下一课的 CDS 指数与基差备好损失分布的语言。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组合损失是 \\(\\mathrm{Loss}=\\sum_i w_i\\,\\mathrm{LGD}_i\\,\\mathbf{1}_{\\tau_i\\le T}\\)。边际违约概率由单名曲线给死，缺口全在联合分布：贷款簿要算 \\(99.9\\%\\) 分位的资本，CDO 分层要算每层的期望损失，指数期权要算远期分布。独立假设直接错：一百个违约率各 \\(1\\%\\) 的名字若相互独立，齐损概率小到天文数字之外；相关一旦上来，尾部齐跌。所以缺口是：如何用少量参数给联合分布定形，并知道每个参数控制的是分布的哪一段。</p><p><span class="marginnote">数字实例：100 个年违约率各 1% 的名字。若完全独立，「一半同时倒」的概率小到宇宙尺度都可忽略；若共享一个 \\(\\rho=0.2\\) 的共同因子，因子落到深处时条件违约率集体跳高，99.9% 分位的损失可以从个位数名字跳到两位数。相关改变的是尾部，几乎不动均值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>市场标准是一因子高斯 copula（机制与批判见<a href="/quant/gaussian-copula-cdo">高斯 Copula 与批判</a>）：每个名字一个潜在变量 \\(X_i=\\sqrt{\\rho}\\,Z+\\sqrt{1-\\rho}\\,\\varepsilon_i\\)，\\(X_i\\) 落到阈值 \\(\\Phi^{-1}(p_i)\\) 之下即违约，\\(Z\\) 是共同因子。给定 \\(Z\\)，条件违约率</p> \\[p(Z)=\\Phi\\!\\left(\\frac{\\Phi^{-1}(p)-\\sqrt{\\rho}\\,Z}{\\sqrt{1-\\rho}}\\right), \\]<p>大组合近似下损失分布的分位数有闭式：</p> \\[\\mathrm{VaR}_{q}=\\Phi\\!\\left(\\frac{\\Phi^{-1}(p)+\\sqrt{\\rho}\\,\\Phi^{-1}(q)}{\\sqrt{1-\\rho}}\\right). \\]<p>这一个公式同时是 Basel 内评法的资本骨架，监管资本课会回到它。名字有限或要分层的细节时用因子模拟：抽 \\(Z\\) 与 \\(\\varepsilon\\)，重演整条损失分布，回收率与 LGD 各自抽分布。保险精算一路是 CreditRisk+：违约计数服从泊松、行业因子造成聚集，不建潜在变量。自上而下一路用组合强度过程直接跳过名字。相关的两套来源要分清：从股票或基本面估计的「真实相关」，与从分层价格反推的基相关——后者是报价坐标，不是资产相关的估计。</p><p><span class="marginnote">copula 翻译一下：一根「把各自边际分布焊成联合分布」的焊枪——每个名字自己的违约概率不变，copula 只决定它们「一起倒」的方式。因子模拟像掷两颗骰子：先掷共同因子 Z（宏观天气），再给每个名字掷噪声 ε（个人体质）；坏天气那段里，体质弱的名字一起违约，聚集与厚尾就是这么来的。</span></p>',13)),(o(),i(A,null,{default:r(()=>[l(e,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20MARG%5B%22%E5%8D%95%E5%90%8D%E6%9B%B2%E7%BA%BF%EF%BC%9A%E8%BE%B9%E9%99%85%20PD%22%5D%20--%3E%20JOINT%5B%22%E8%81%94%E5%90%88%E5%88%86%E5%B8%83%EF%BC%9A%E4%B8%80%E5%9B%A0%E5%AD%90%20copula%22%5D%0A%20%20JOINT%20--%3E%20PZ%5B%22%E6%9D%A1%E4%BB%B6%E8%BF%9D%E7%BA%A6%E7%8E%87%20p(Z)%22%5D%0A%20%20PZ%20--%3E%20TAIL%5B%22%E5%B0%BE%E9%83%A8%EF%BC%9AVaR%20%E4%B8%8E%20ES%20%E9%9A%8F%20rho%20%E6%94%BE%E5%A4%A7%22%5D%0A%20%20JOINT%20--%3E%20SIM%5B%22%E5%9B%A0%E5%AD%90%E6%A8%A1%E6%8B%9F%EF%BC%9ALGD%20%E4%B8%8E%E5%9B%9E%E6%94%B6%E5%88%86%E5%BC%80%E6%8A%BD%22%5D%0A%20%20JOINT%20--%3E%20CRP%5B%22CreditRisk%2B%EF%BC%9A%E6%B3%8A%E6%9D%BE%E8%81%9A%E9%9B%86%22%5D%0A%20%20TAIL%20--%3E%20TRA%5B%22%E5%88%86%E5%B1%82%E5%AE%9A%E4%BB%B7%E4%B8%8E%E8%B5%84%E6%9C%AC%E8%AE%A1%E9%87%8F%22%5D%0A"})]),fallback:r(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("\\(\\rho\\) 是尾部的总开关：\\(\\rho=0\\) 退回独立，分散化完全有效；\\(\\rho\\to 1\\) 组合退化为单一赌注，\\(\\mathrm{VaR}_q\\) 趋向名义全额。闭式还暴露一个常被忽略的事实：分位点 \\(q\\) 从 \\(99\\%\\) 提到 \\(99.9\\%\\)，要求的资本可以翻倍以上，因为增幅全被 \\(\\sqrt{\\rho}\\) 放大——「平均违约率很低」与「资本很充足」是两句话。集中度是第二条放大通道：单名或单一行业权重上升时大组合近似失效，要用集中度修正或退回全模拟。回收假设的系统性偏差（"),B("a",{href:"/quant/recovery-assumption"},"回收假设"),a("一课）在组合层面被再放大一次：违约相关高的时期，回收往往也系统性偏低，PD 与 LGD 独立的假设恰在尾部最不成立。")],-1)),(o(),i(A,null,{default:r(()=>[l(e,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20RHO0%5B%22rho%20%3D%200%EF%BC%9A%E7%8B%AC%E7%AB%8B%22%5D%20--%3E%20EFF%5B%22%E5%88%86%E6%95%A3%E5%8C%96%E5%AE%8C%E5%85%A8%E6%9C%89%E6%95%88%EF%BC%8C%E5%B0%BE%E9%83%A8%E5%BE%88%E8%96%84%22%5D%0A%20%20RHO1%5B%22rho%20%E8%B6%8B%E5%90%91%201%22%5D%20--%3E%20ONE%5B%22%E7%BB%84%E5%90%88%E9%80%80%E5%8C%96%E4%B8%BA%E5%8D%95%E4%B8%80%E8%B5%8C%E6%B3%A8%22%5D%0A%20%20QQ%5B%22%E5%88%86%E4%BD%8D%E7%82%B9%20q%20%E4%BB%8E%2099%25%20%E6%8F%90%E5%88%B0%2099.9%25%22%5D%20--%3E%20CAP%5B%22%E8%B5%84%E6%9C%AC%E5%8F%AF%E7%BF%BB%E5%80%8D%E4%BB%A5%E4%B8%8A%EF%BC%8C%E5%A2%9E%E5%B9%85%E8%A2%AB%20sqrt%20rho%20%E6%94%BE%E5%A4%A7%22%5D%0A%20%20CONC%5B%22%E5%8D%95%E5%90%8D%E6%88%96%E8%A1%8C%E4%B8%9A%E9%9B%86%E4%B8%AD%E5%BA%A6%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20FAIL%5B%22%E5%A4%A7%E7%BB%84%E5%90%88%E8%BF%91%E4%BC%BC%E5%A4%B1%E6%95%88%22%5D%0A%20%20FAIL%20--%3E%20FIX%5B%22%E9%9B%86%E4%B8%AD%E5%BA%A6%E4%BF%AE%E6%AD%A3%E6%88%96%E9%80%80%E5%9B%9E%E5%85%A8%E6%A8%A1%E6%8B%9F%22%5D%0A%20%20RECOV%5B%22%E5%8D%B1%E6%9C%BA%E6%9C%9F%E5%9B%9E%E6%94%B6%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%81%8F%E4%BD%8E%22%5D%20--%3E%20WORSE%5B%22PD%20%E4%B8%8E%20LGD%20%E7%8B%AC%E7%AB%8B%E5%81%87%E8%AE%BE%E5%9C%A8%E5%B0%BE%E9%83%A8%E5%A4%B1%E6%95%88%22%5D%0A"})]),fallback:r(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">Basel 内评法把分位点钉在 \\(99.9\\%\\)，并给资产相关性设定监管值：公司贷款按 PD 在约 12% 到 24% 之间、住房抵押约 15%。监管没有假装知道每家银行的真实 \\(\\rho\\)，而是用保守分位加统一定标，把不同银行的资本博弈压到同一张表上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>高斯 copula 是静态且薄尾的：它给「到某日为止」的联合违约定形，不描述违约的时间到达与传染；把静态惯例外推成损失生成过程，正是 2008 年教训的核心（同上引课的批判）。动态模型——自上而下强度、马尔可夫链式传染——是另一条路线，本课程不展开。基相关只在分层市场活跃时可得，流动性消失时它是没有任何成交支撑的记账。本课不写指数与基差的市场机制，那是下一课；也不写巴塞尔公式的计提细节，留给监管资本课。最后，模型输出是分布不是价格：把 \\(\\mathrm{VaR}_{99.9}\\) 直接当转移价格用，混淆了资本计量与定价两个用途，它怎么进报价在监管资本课再谈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>信用组合的缺口在联合分布：边际 PD 由单名曲线给死，相关决定尾部。</li><li>一因子高斯 copula 用一个 \\(\\rho\\) 控尾部，大组合分位数闭式可写，也是 Basel IRB 的骨架。</li><li>相关的两套坐标要分清：真实相关是估计，基相关是报价。</li><li>集中度与 PD–LGD 相关在尾部二次放大风险，独立假设最不成立的地方恰是资本所在。</li><li>出处：Vasicek, <em>Risk</em>, 2002；Li, <em>Journal of Fixed Income</em>, 2000；copula 批判与回收见本栏 gaussian-copula-cdo、recovery-assumption 两课。</li></ul>',5))])}const q=s(h,[["render",D]]);export{_ as __pageData,q as default};
